function payWorker(s,t){var w=U(s.worker);if(!w)return;s.status='approved';w.earned=r3(w.earned+t.price);w.totalEarned=r3(w.totalEarned+t.price);w.tasksDone++;fin('payout',t.price);updHist(s.id,'approved');notify(w.id,'Your proof for "'+t.title+'" was approved. +'+money(t.price));
  var rf=w.refBy&&U(w.refBy);if(rf){var c=r3(t.price*S.set.refPct/100);if(c>0){rf.earned=r3(rf.earned+c);rf.totalEarned=r3(rf.totalEarned+c);fin('comm',c);hist(rf.id,{type:'ref',title:'Referral Commission '+S.set.refPct+'% from '+w.name,amt:c,status:'approved',reason:''});notify(rf.id,'Referral commission '+money(c)+' from '+w.name)}}
  if(done(t.id)>=t.workers&&t.status!=='deleted'){t.status='completed'}}
function settleDelete(t){subsOf(t.id).forEach(function(s){if(s.status==='pending')payWorker(s,t)});var un=Math.max(0,t.workers-live(t.id)),b=U(t.buyer);if(b&&un>0){b.deposit=r3(b.deposit+un*unit(t))}t.status='deleted';t.settled=true;t.delReq=false;if(b)notify(b.id,'Task "'+t.title+'" deleted. '+money(un*unit(t))+' refunded.')}
function canDo(t,u){if(t.buyer===u.id)return 'This is your own task';if(t.status!=='active')return 'Task is not active';if(t.expires<now())return 'Task expired';if(subsOf(t.id).some(function(s){return s.worker===u.id}))return 'You already submitted this task';if(live(t.id)>=t.workers)return 'No slots left';if(t.vonly&&!u.verified)return 'Verified workers only';return ''}
