A.askdel=function(v){openSheet('<h3>Delete this task?</h3><p>The request goes to admin. After approval, workers with submitted proofs are paid and the unused slots are refunded to your deposit balance.</p><div class="g2"><button class="btn" data-a="close">Keep task</button><button class="btn r" data-a="confdel" data-v="'+v+'">Send request</button></div>')};
A.confdel=function(v){var t=T(v);t.delReq=true;save();closeLayer();R();toast('Delete request sent to admin')};
A.asktop=function(v){openSheet('<h3>Make this a TOP JOB?</h3><p>Top Job for 1 day costs <b>'+money(S.set.topFee)+'</b>. The amount is charged only when you confirm.</p><div class="g2"><button class="btn" data-a="close">Cancel</button><button class="btn g" data-a="conftop" data-v="'+v+'">Confirm and pay</button></div>')};
A.conftop=function(v){var t=T(v),u=me();if(u.deposit<S.set.topFee){closeLayer();return toast('Not enough deposit balance')}u.deposit=r3(u.deposit-S.set.topFee);u.spent=r3(u.spent+S.set.topFee);fin('fee',S.set.topFee);fin('taskadd',S.set.topFee);t.top=Math.max(t.top,now())+DAY;save();closeLayer();R();toast('Top Job activated for 1 day')};
A.expand=function(v){ui.exp=ui.exp===v?null:v;ui.rej=null;R()};
A.approve=function(v){var s=S.subs.find(function(x){return x.id===v}),t=T(s.task);if(s.status!=='pending')return;payWorker(s,t);ui.exp=null;save();R();toast('Approved. '+money(t.price)+' added to worker')};
