A.reject=function(v){var r=val('rr').trim();if(!r)return toast('Write a reason first');var s=S.subs.find(function(x){return x.id===v});s.status='rejected';s.reason=r;updHist(s.id,'rejected',r);notify(s.worker,'Your proof for "'+T(s.task).title+'" was rejected: '+r);ui.exp=null;ui.rej=null;save();R();toast('Rejected')};
