A.chatfile=function(){pick(function(d){ui.chatShot=d;toast('Image attached. Press send.')})};
A.chatsend=function(v){var p=v.split(':'),side=p[0],k=p[1],tx=val('cm').trim();if(!tx&&!ui.chatShot)return;var c=S.chats[k];if(!c)c=S.chats[k]={msgs:[],inChat:side==='user',lastTs:now(),auto:false};c.msgs.push({from:side,text:tx,img:ui.chatShot,ts:now()});c.lastTs=now();ui.chatShot=null;
  if(side==='user'&&!c.auto&&S.set.autoReply){c.auto=true;c.msgs.push({from:'admin',text:S.set.autoReply,ts:now()+1})}save();R();var i=$('#cm');if(i)i.focus()};
