A.depok=function(v){var d=S.deps.find(function(x){return x.id===v}),u=U(d.uid),m=S.methods.find(function(x){return x.id===d.mid}),b=m&&m.bonus?r3(d.amt*m.bonus/100):0;d.status='approved';u.deposit=r3(u.deposit+d.amt+b);fin('dep',d.amt);updHist(d.id,'approved');notify(u.id,'Deposit '+money(d.amt)+' approved'+(b?' (+'+money(b)+' bonus)':'')+'.');save();R();toast('Deposit approved')};
A.deprej=function(v){openSheet('<h3>Reject deposit</h3><label class="lbl" for="rsn">Reason</label><input class="inp" id="rsn"><div style="height:10px"></div><button class="btn r" data-a="deprej2" data-v="'+v+'">Reject</button>')};
A.deprej2=function(v){var r=val('rsn').trim();if(!r)return toast('Write a reason');var d=S.deps.find(function(x){return x.id===v});d.status='rejected';d.reason=r;updHist(d.id,'rejected',r);notify(d.uid,'Deposit rejected: '+r);save();closeLayer();R()};
A.wdok=function(v){var d=S.wds.find(function(x){return x.id===v});d.status='approved';fin('wd',d.amt);updHist(d.id,'approved');notify(d.uid,'Withdrawal '+money(d.amt)+' approved and sent.');save();R();toast('Withdraw approved')};
A.wdrej=function(v){openSheet('<h3>Reject withdraw</h3><p class="mut">The money returns to the user’s earned balance.</p><label class="lbl" for="rsn">Reason (optional)</label><input class="inp" id="rsn"><div style="height:10px"></div><button class="btn r" data-a="wdrej2" data-v="'+v+'">Reject and refund</button>')};
A.wdrej2=function(v){var d=S.wds.find(function(x){return x.id===v}),u=U(d.uid),r=val('rsn').trim();d.status='rejected';d.reason=r;u.earned=r3(u.earned+d.amt);updHist(d.id,'rejected',r);notify(d.uid,'Withdrawal rejected'+(r?': '+r:'')+'. '+money(d.amt)+' returned.');save();closeLayer();R()};
A.uver=function(v){var u=U(v);u.verified=!u.verified;u.verifyReq=false;save();R()};A.uban=function(v){var u=U(v);u.ban=!u.ban;save();R()};
A.ubal=function(v){var p=v.split(':'),u=U(p[0]),a=+val('ba'+p[0]);if(!a)return toast('Enter an amount');u[p[1]]=r3(Math.max(0,u[p[1]]+a));if(p[1]==='earned'&&a>0){u.totalEarned=r3(u.totalEarned+a);hist(u.id,{type:'bonus',title:'Bonus '+money(a)+' Admin Reward',amt:a,status:'approved',reason:''})}save();R();toast('Balance updated')};
