document.addEventListener('input',function(e){var i=e.target.dataset&&e.target.dataset.i;if(!i)return;var el=e.target;
  if(i==='q'){ui.q=el.value;var l=$('#tl');if(l)l.innerHTML=taskCards()}
  else if(i==='aq'){ui.adminQ=el.value;var q=el.value.toLowerCase();$('#ul').innerHTML=usersList(S.users.filter(function(u){return!q||(u.name+u.ec+u.email).toLowerCase().indexOf(q)>-1}))}
  else if(i==='wam'){var a=+el.value||0;$('#wbdt').firstChild.textContent='≈ ৳'+Math.round(a*S.set.rate)+' BDT '}
  else if(i==='calc')calcCreate();
  else if(i==='price'){var v=+el.value;if(v>0){S.prices[el.dataset.c][el.dataset.k]=v;save()}}
  else if(i==='mnum'){S.methods[+el.dataset.k].num=el.value;save()}
  else if(i==='mcap'){S.set.caption=el.value;save()}
  else if(i==='stext'){S.set[el.dataset.k]=el.value;save()}
  else if(i==='set'){var n=+el.value;if(n>=0){S.set[el.dataset.k]=n;save()}}});
